#!/usr/bin/env python3
import gzip
import json
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from collections import Counter, defaultdict


STD_CHROMS = {f"chr{i}" for i in range(1, 23)} | {"chrX", "chrY"}
BASES = "ACGT"
RC = str.maketrans("ACGTacgt", "TGCAtgca")


def open_text(path):
    if path.endswith(".gz"):
        return gzip.open(path, "rt")
    return open(path, "rt")


def read_fragments(path, limit):
    rows = []
    seen = 0
    with open_text(path) as handle:
        for line in handle:
            if not line.strip() or line.startswith("#"):
                continue
            fields = line.rstrip("\n").split("\t")
            if len(fields) < 3:
                continue
            chrom = fields[0]
            if chrom not in STD_CHROMS:
                continue
            try:
                start = int(fields[1])
                end = int(fields[2])
            except ValueError:
                continue
            if start < 100 or end <= start + 20:
                continue
            seen += 1
            if len(rows) < limit:
                rows.append((chrom, start, end))
            else:
                # Deterministic thinning keeps coverage across the whole file.
                slot = seen % limit
                if slot == 0:
                    rows[seen % len(rows)] = (chrom, start, end)
    return rows, seen


def fetch_sequence(chrom, start, end, retries=3):
    query = urllib.parse.urlencode(
        {"genome": "hg38", "chrom": chrom, "start": start, "end": end}
    )
    url = "https://api.genome.ucsc.edu/getData/sequence?" + query
    for attempt in range(retries):
        try:
            with urllib.request.urlopen(url, timeout=30) as response:
                data = json.loads(response.read().decode("utf-8"))
            dna = data.get("dna", "").upper()
            if len(dna) == end - start:
                return dna
            return None
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError):
            if attempt + 1 == retries:
                return None
            time.sleep(1 + attempt)
    return None


def add_counts(counts, seq):
    for i, base in enumerate(seq.upper()):
        if base in BASES:
            counts[i][base] += 1


def consensus(counts):
    letters = []
    for pos in sorted(counts):
        total = sum(counts[pos].values())
        if total == 0:
            letters.append("N")
            continue
        base, n = max(counts[pos].items(), key=lambda item: item[1])
        letters.append(base.lower() if n / total < 0.35 else base)
    return "".join(letters)


def information_rows(label, counts, flank):
    rows = []
    for i in range(2 * flank):
        total = sum(counts[i].values())
        if total == 0:
            continue
        freqs = {b: counts[i][b] / total for b in BASES}
        major = max(BASES, key=lambda b: freqs[b])
        rows.append(
            [
                label,
                str(i - flank),
                str(total),
                major,
                *(f"{freqs[b]:.4f}" for b in BASES),
            ]
        )
    return rows


def main():
    frag_path, out_path = sys.argv[1:3]
    flank = int(sys.argv[3]) if len(sys.argv) > 3 else 20
    limit = int(sys.argv[4]) if len(sys.argv) > 4 else 500
    fragments, usable_rows = read_fragments(frag_path, limit)

    start_counts = defaultdict(Counter)
    end_counts = defaultdict(Counter)
    used = 0
    failed = 0
    for chrom, start, end in fragments:
        left = fetch_sequence(chrom, start - flank, start + flank)
        right = fetch_sequence(chrom, end - flank, end + flank)
        if left is None or right is None:
            failed += 1
            continue
        add_counts(start_counts, left)
        add_counts(end_counts, right.translate(RC)[::-1])
        used += 1

    with open(out_path, "w") as out:
        out.write("# ATAC fragment shift diagnostic around observed endpoints\n")
        out.write(f"# usable_rows_in_file\t{usable_rows}\n")
        out.write(f"# sampled_fragments\t{len(fragments)}\n")
        out.write(f"# sequence_pairs_used\t{used}\n")
        out.write(f"# sequence_pairs_failed\t{failed}\n")
        out.write(f"# flank\t{flank}\n")
        out.write(f"# start_consensus\t{consensus(start_counts)}\n")
        out.write(f"# end_rc_consensus\t{consensus(end_counts)}\n")
        out.write("endpoint\trel_pos\tn\tmajor\tA\tC\tG\tT\n")
        for row in information_rows("start", start_counts, flank):
            out.write("\t".join(row) + "\n")
        for row in information_rows("end_rc", end_counts, flank):
            out.write("\t".join(row) + "\n")


if __name__ == "__main__":
    main()

