#!/usr/bin/env python3
import gzip
import hashlib
import json
import math
import sys
import time
import urllib.error
import urllib.parse
import urllib.request


STD_CHROMS = {f"chr{i}" for i in range(1, 23)} | {"chrX", "chrY"}
RC = str.maketrans("ACGTacgt", "TGCAtgca")
F_URL = "https://raw.githubusercontent.com/CostaLab/reg-gen/master/data/fp_hmms/atac_bias_table_F.txt"
R_URL = "https://raw.githubusercontent.com/CostaLab/reg-gen/master/data/fp_hmms/atac_bias_table_R.txt"


def open_text(path):
    return gzip.open(path, "rt") if path.endswith(".gz") else open(path, "rt")


def read_fragments(path, limit):
    rows = []
    seen = 0
    with open_text(path) as handle:
        for line in handle:
            if not line.strip() or line.startswith("#"):
                continue
            fields = line.rstrip("\n").split("\t")
            if len(fields) < 3 or fields[0] not in STD_CHROMS:
                continue
            try:
                start = int(fields[1])
                end = int(fields[2])
            except ValueError:
                continue
            if start < 100 or end <= start + 20:
                continue
            seen += 1
            if len(rows) < limit:
                rows.append((fields[0], start, end))
            else:
                slot = seen % limit
                if slot == 0:
                    rows[(seen // limit) % len(rows)] = (fields[0], start, end)
    return rows, seen


def fetch_url(url):
    with urllib.request.urlopen(url, timeout=60) as response:
        return response.read()


def load_bias_table(url):
    raw = fetch_url(url)
    table = {}
    for line in raw.decode("utf-8").splitlines():
        if not line.strip():
            continue
        kmer, value = line.split()[:2]
        table[kmer.upper()] = float(value)
    return table, hashlib.sha256(raw).hexdigest(), len(raw)


def fetch_sequence(chrom, start, end, retries=3):
    query = urllib.parse.urlencode(
        {"genome": "hg38", "chrom": chrom, "start": start, "end": end}
    )
    url = "https://api.genome.ucsc.edu/getData/sequence?" + query
    for attempt in range(retries):
        try:
            with urllib.request.urlopen(url, timeout=30) as response:
                data = json.loads(response.read().decode("utf-8"))
            dna = data.get("dna", "").upper()
            return dna if len(dna) == end - start else None
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError):
            if attempt + 1 == retries:
                return None
            time.sleep(1 + attempt)
    return None


def mean(values):
    return sum(values) / len(values) if values else float("nan")


def stdev(values):
    if len(values) < 2:
        return float("nan")
    m = mean(values)
    return math.sqrt(sum((x - m) ** 2 for x in values) / (len(values) - 1))


def main():
    frag_path, out_path = sys.argv[1:3]
    sample_limit = int(sys.argv[3]) if len(sys.argv) > 3 else 1500
    max_delta = int(sys.argv[4]) if len(sys.argv) > 4 else 14
    context = max_delta + 8
    f_table, f_sha, f_bytes = load_bias_table(F_URL)
    r_table, r_sha, r_bytes = load_bias_table(R_URL)

    fragments, usable_rows = read_fragments(frag_path, sample_limit)
    pairs = []
    failed = 0
    for chrom, start, end in fragments:
        left = fetch_sequence(chrom, start - context, start + context + 1)
        right = fetch_sequence(chrom, end - context, end + context + 1)
        if left is None or right is None:
            failed += 1
            continue
        pairs.append((left, right))

    candidates = []
    pseudocount = 1e-6
    for shift5 in range(-6, 13):
        delta5 = 4 - shift5
        if abs(delta5) > max_delta:
            continue
        for shift3 in range(-16, 7):
            delta3 = -5 - shift3
            if abs(delta3) > max_delta:
                continue
            f_scores = []
            r_scores = []
            used = 0
            for left, right in pairs:
                c5 = context + delta5
                c3 = context + delta3
                # RGT/HINT k=8 convention: forward kmer [cut-4, cut+4),
                # reverse kmer reverse-complemented from [cut-3, cut+5).
                f_kmer = left[c5 - 4 : c5 + 4]
                r_kmer = right[c3 - 3 : c3 + 5].translate(RC)[::-1]
                if len(f_kmer) != 8 or len(r_kmer) != 8:
                    continue
                if "N" in f_kmer or "N" in r_kmer:
                    continue
                f_scores.append(math.log(f_table.get(f_kmer, pseudocount)))
                r_scores.append(math.log(r_table.get(r_kmer, pseudocount)))
                used += 1
            if used < max(50, len(pairs) // 2):
                continue
            all_scores = f_scores + r_scores
            candidates.append(
                (
                    mean(all_scores),
                    mean(f_scores),
                    mean(r_scores),
                    stdev(all_scores),
                    used,
                    shift5,
                    shift3,
                    delta5,
                    delta3,
                )
            )

    candidates.sort(reverse=True)
    with open(out_path, "w") as out:
        out.write("# ATAC shift scoring against public RGT/HINT ATAC bias tables\n")
        out.write(f"# bias_F_url\t{F_URL}\n")
        out.write(f"# bias_F_sha256\t{f_sha}\n")
        out.write(f"# bias_F_bytes\t{f_bytes}\n")
        out.write(f"# bias_R_url\t{R_URL}\n")
        out.write(f"# bias_R_sha256\t{r_sha}\n")
        out.write(f"# bias_R_bytes\t{r_bytes}\n")
        out.write(f"# usable_rows_in_file\t{usable_rows}\n")
        out.write(f"# sampled_fragments\t{len(fragments)}\n")
        out.write(f"# sequence_pairs_used\t{len(pairs)}\n")
        out.write(f"# sequence_pairs_failed\t{failed}\n")
        if candidates:
            out.write(f"# best_shift\t{candidates[0][5]};{candidates[0][6]}\n")
            out.write(f"# best_delta_to_standard_cut\t{candidates[0][7]};{candidates[0][8]}\n")
        out.write("rank\tmean_log_bias\tforward_mean\treverse_mean\tstdev\tn\tshift5\tshift3\tdelta5\tdelta3\n")
        for rank, row in enumerate(candidates[:100], 1):
            out.write(
                "\t".join(
                    [
                        str(rank),
                        f"{row[0]:.6f}",
                        f"{row[1]:.6f}",
                        f"{row[2]:.6f}",
                        f"{row[3]:.6f}",
                        str(row[4]),
                        str(row[5]),
                        str(row[6]),
                        str(row[7]),
                        str(row[8]),
                    ]
                )
                + "\n"
            )


if __name__ == "__main__":
    main()

